    out = [row[:] for row in grid]

    # In the large figure, each 2x2 block is a unit. Color blocks by
    # matching the small colored pattern's spatial arrangement to the
    # occupied blocks in the figure.
    clue = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
            if grid[r][c] not in (0, 8)]
    if not clue:
        return out

    # Locate the 8-pattern's occupied 2x2 cells.
    blocks = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8:
                blocks.add((r // 2, c // 2))

    # The clue is a small colored pattern. Its distinct colored objects
    # correspond to the large pattern's block groups in reading order.
    colors = []
    seen = set()
    for r, c, v in clue:
        if v not in seen:
            seen.add(v)
            colors.append(v)

    # Apply colors in broad horizontal bands, preserving the shape.
    rows = sorted(set(r for r, c in blocks))
    for i, br in enumerate(rows):
        color = colors[min(i, len(colors) - 1)]
        for r, c in blocks:
            if r == br:
                for rr in range(2 * r, min(2 * r + 2, h)):
                    for cc in range(2 * c, min(2 * c + 2, w)):
                        if grid[rr][cc] == 8:
                            out[rr][cc] = color
    return out
